// The scene table, shared by the sequencer (main.c), the remote (remote.c) and the offscreen tool
// (tools/preview.c). Every scene has a channel number, the way a TV remote sees it:
//   0        standby (black picture)
//   1..      the default loop in play order
//   20..     the extras, selectable by name or number only (slides, test card)
//   30..     uploaded visuals (visuals/*.c, alphabetical; table generated by tools/gen-visuals.sh)
#pragma once
#include "core.h"

#include <stddef.h>

#define CH_EXTRA 20
#define CH_VISUAL 30
#define CH_MAX 99

extern const Scene *const scene_loop[];    // the default loop, in play order
extern const Scene *const scene_extra[];   // selectable by name or channel only
extern const Scene *const scene_visuals[]; // uploaded, from build/visuals.c
extern const int scene_nloop, scene_nextra, scene_nvisuals;
extern const Scene scene_black;            // channel 0

const Scene *scene_find(const char *name); // every table; NULL if unknown
const Scene *scene_parse(const char *s);   // a name or a channel number; NULL if unknown
int scene_channel(const Scene *sc);        // -1 if the scene is in no table
const Scene *scene_by_channel(int ch);     // NULL if the number is unused
const char *scene_kind(const Scene *sc);   // "standby", "loop", "extra", "visual"
size_t scene_list_str(char *out, size_t n); // one line per channel: number, name, duration, kind
void scene_list(void);                     // the same on stdout
